-- 열정페이 / 디벨롭 / 컨펌 / 일잘러 / 고스팅 / 중고신입 추가 (489-494, 2026-09-14 아침 검수 승인 — slang_candidates draft_payload 그대로).
-- 여섯 개 모두 [표준사전: 없음], 독립 출처 3~4개로 뜻 교차 확인.
-- 열정페이: 2015 KBS 추적 60분이 공론화 계기(위키백과·나무위키). 최초 사용 시점은 미상이라 적지 않았다.
-- 디벨롭·컨펌: 2017 급여체 보도의 대표 콩글리시. 광고·디자인 업계 발원설은 근거가 없어 설로만 적었다.
-- 일잘러: -러 접미사 조어 흐름. related의 일못러는 아직 표제어가 아니다.
-- 고스팅: 연애/채용 중 어느 뜻이 먼저인지 출처가 갈려 category=work, secondary_category=love로 양쪽을 잡았다.
-- 중고신입: 평균 2.3년차·32.3세는 사람인 560개사 설문(출처 1곳). 등장 시점은 특정하지 않았다.
-- related_words 중 급여체·이퇴백(보류)과 문송합니다(실전 표현으로 이관)는 아직 표제어가 아니다.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('489', '열정페이', 'Yeol-jeong-pe-i', 'work', null, '열정을 핑계로 제대로 주지 않는 임금', '{"de": "Leidenschaftslohn — Hungerlohn im Namen des Traums", "en": "Passion pay — wages withheld in the name of your dream", "es": "Sueldo de la pasión: pagar poco en nombre del sueño", "ja": "情熱を口実にした低賃金", "vi": "Lương đam mê — trả rẻ mạt nhân danh ước mơ"}'::jsonb, '[열쩡페이]', '[{"type": "명사", "examples": [{"de": "600.000 Won im Monat für eine Sechstagewoche? Das ist reiner Leidenschaftslohn.", "es": "¿600.000 wones al mes por seis días? Eso es sueldo de la pasión y ya.", "ja": "月60万ウォンで週6日?それ完全に情熱ペイでしょ。", "vi": "600 nghìn won một tháng mà làm sáu ngày? Đó đúng là lương đam mê.", "eng": "600,000 won a month for a six-day week? That is just passion pay.", "kor": "월 60만 원에 주 6일? 그거 그냥 열정페이잖아."}], "definition": "열정(熱情)과 페이(pay)의 합성어. 하고 싶은 일을 하게 해 줬다는 구실로 청년 구직자에게 무급이나 최저임금에도 못 미치는 돈을 주는 저임금 노동. 착취를 비꼬는 말이라 늘 부정적으로 쓴다.", "definition_i18n": {"de": "열정(Leidenschaft) + pay. Junge Bewerber*innen gar nicht oder unter Mindestlohn bezahlen, mit der Ausrede, sie dürften ihrem Traum nachgehen. Immer kritisch — es benennt Ausbeutung.", "en": "열정(passion) + pay. Paying young job-seekers nothing or below minimum wage on the excuse that they were allowed to do what they love. Always used critically — it names exploitation.", "es": "열정(pasión) + pay. Pagar nada o menos del mínimo a jóvenes con la excusa de dejarles hacer lo que aman. Siempre crítico: nombra la explotación.", "ja": "열정(情熱)+pay。やりたい仕事をさせてやったという口実で、若い求職者に無給や最低賃金未満しか払わない低賃金労働。搾取を皮肉る語で常に否定的に使う。", "vi": "열정(đam mê) + pay. Trả công không lương hoặc dưới mức tối thiểu cho người trẻ, lấy cớ đã cho họ làm việc mình thích. Luôn mang nghĩa phê phán sự bóc lột."}}]'::jsonb, '2010년대 초중반 패션·디자인·방송 등 이른바 꿈의 직업 업계의 무급 인턴 관행을 비판하며 퍼졌다. 2015년 3월 7일 KBS 추적 60분이 실태를 방영하면서 사회적으로 공론화됐고 그 무렵 신조어로 굳어졌다. 누가 처음 만든 말인지는 확인되지 않았다.', '{"de": "Verbreitete sich Anfang bis Mitte der 2010er als Kritik an unbezahlten Praktika in sogenannten Traumbranchen — Mode, Design, Rundfunk. Eine KBS-Doku vom 7. März 2015 machte es zum öffentlichen Thema. Der Urheber ist unbekannt.", "en": "Spread in the early-to-mid 2010s as criticism of unpaid internships in so-called dream industries — fashion, design, broadcasting. A KBS documentary on 7 March 2015 pushed it into public debate and cemented it as a coinage. The original coiner is unknown.", "es": "Se difundió a principios y mediados de los 2010 criticando las prácticas no remuneradas en sectores de ensueño: moda, diseño, televisión. Un reportaje de KBS del 7 de marzo de 2015 lo llevó al debate público. Se desconoce quién lo acuñó.", "ja": "2010年代前半から中盤、ファッション・デザイン・放送などいわゆる夢の職業業界の無給インターン慣行を批判する中で広まった。2015年3月7日KBS追跡60分が実態を放映し社会問題化、その頃に新語として定着。造語者は不明。", "vi": "Lan rộng đầu và giữa thập niên 2010 khi phê phán thực tập không lương ở các ngành nghề mơ ước: thời trang, thiết kế, truyền hình. Phóng sự KBS ngày 7/3/2015 đưa nó ra công luận. Không rõ ai đặt ra từ này."}'::jsonb, '열정페이 강요하지 마세요처럼 고발하거나 항의하는 맥락에서 쓴다. 고용주 앞에서 쓰면 정면 비판이 되므로, 보통은 친구·커뮤니티에 조건을 이야기할 때 등장한다.', '{"de": "Dient der Anklage: 열정페이 강요하지 마세요. Gegenüber Arbeitgebern ist es ein direkter Vorwurf, es fällt daher meist im Gespräch mit Freund*innen oder online.", "en": "Used to call something out — 열정페이 강요하지 마세요 (stop demanding passion pay). Saying it to an employer is a direct accusation, so it mostly turns up when describing an offer to friends or online.", "es": "Se usa para denunciar: 열정페이 강요하지 마세요. Dicho al empleador es una acusación directa, así que suele aparecer al contar las condiciones a amigos o en foros.", "ja": "열정페이 강요하지 마세요のように告発・抗議の文脈で使う。雇用主の前で使えば正面からの批判になるため、普通は友人やコミュニティで条件を話すときに出る。", "vi": "Dùng khi tố cáo, phản đối: 열정페이 강요하지 마세요. Nói thẳng với chủ là chỉ trích trực diện, nên thường chỉ xuất hiện khi kể điều kiện với bạn bè hay trên mạng."}'::jsonb, '{흙수저,헬조선,이퇴백,갓생}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Passion pay (exploitative low wage)"}, {"lang": "🇯🇵 JA", "text": "情熱ペイ(やりがい搾取)"}, {"lang": "🇨🇳 ZH", "text": "热情工资(压榨低薪)"}, {"lang": "🇻🇳 VI", "text": "Lương đam mê (bóc lột)"}, {"lang": "🇪🇸 ES", "text": "Sueldo de la pasión"}, {"lang": "🇩🇪 DE", "text": "Leidenschaftslohn"}]'::jsonb),
('490', '디벨롭', 'Di-bel-lop', 'work', null, '기획안을 더 발전시키라는 뜻', '{"de": "Arbeite das weiter aus", "en": "Flesh this out more", "es": "Desarróllalo más", "ja": "もっと詰めてこい", "vi": "Làm kỹ thêm đi"}'::jsonb, '[디벨롭]', '[{"type": "명사/동사", "examples": [{"de": "Arbeite das Konzept noch etwas aus und gib es mir bis morgen früh.", "es": "Desarrolla un poco más esta propuesta y me la pasas mañana por la mañana.", "ja": "この企画、もう少し詰めて明日の朝までにください。", "vi": "Kế hoạch này làm kỹ thêm rồi sáng mai gửi tôi nhé.", "eng": "Flesh out this proposal a bit more and get it to me by tomorrow morning.", "kor": "이 기획안 좀 더 디벨롭해서 내일 아침까지 주세요."}], "definition": "영어 develop에서 온 회사 용어. 내용이 부실하니 살을 붙여 더 발전시키라는 뜻. 디벨롭해 주세요는 겉으로는 부드럽지만 사실상 다시 해 오세요에 가까워, 듣는 순간 야근을 각오하게 되는 말로 통한다.", "definition_i18n": {"de": "Büro-Konglish von develop: der Inhalt ist dünn, leg nach. 디벨롭해 주세요 klingt sanft, heißt aber faktisch mach es neu — für viele die Ansage für Überstunden.", "en": "Office Konglish from develop: the content is thin, go add substance. 디벨롭해 주세요 sounds gentle but effectively means do it again — office workers hear it as a night-shift warning.", "es": "Konglish de oficina, de develop: el contenido es flojo, dale cuerpo. 디벨롭해 주세요 suena suave pero equivale a rehazlo — se oye como aviso de horas extra.", "ja": "英語develop由来の会社用語。内容が薄いので肉付けして発展させろという意味。디벨롭해 주세요は柔らかく聞こえるが実質やり直しに近く、聞いた瞬間に残業を覚悟する言葉とされる。", "vi": "Từ công sở gốc develop: nội dung còn mỏng, hãy bồi đắp thêm. 디벨롭해 주세요 nghe nhẹ nhàng nhưng thực chất là làm lại đi — nghe xong là biết phải tăng ca."}}]'::jsonb, '컨펌과 함께 2017년 급여체 보도에서 대표 사례로 꼽힌 콩글리시 업무 용어. 광고·기획 직군에서 먼저 쓰였다는 이야기가 많지만 정확한 유입 시점과 경로는 확인되지 않았다.', '{"de": "Büro-Konglish, in der Berichterstattung 2017 zu 급여체 neben 컨펌 hervorgehoben. Oft mit Werbung und Planung in Verbindung gebracht, Weg und Zeitpunkt aber unbelegt.", "en": "Office Konglish singled out alongside 컨펌 in 2017 press coverage of corporate-speak. Often said to have started in advertising and planning roles, but the exact route and date are unverified.", "es": "Konglish de oficina destacado junto a 컨펌 en la cobertura de 2017 sobre 급여체. Se dice que empezó en publicidad y planificación, pero ruta y fecha están sin verificar.", "ja": "2017年の급여체報道で컨펌と並び代表例に挙げられたコングリッシュ業務用語。広告・企画職から広まったとよく言われるが、流入時期と経路は未確認。", "vi": "Từ Konglish công sở, được nêu cùng 컨펌 trong loạt bài 2017 về 급여체. Nhiều người bảo nó khởi từ ngành quảng cáo, lập kế hoạch, nhưng chưa xác minh được."}'::jsonb, '디벨롭하다·디벨롭시키다로 쓴다. 위에서 아래로 내려가는 지시라, 신입이 상사 기획안을 두고 디벨롭이 필요해 보입니다라고 하면 무례하게 들린다. 동료끼리는 같이 디벨롭해 보자처럼 쓰면 자연스럽다.', '{"de": "Gebraucht als 디벨롭하다 / 디벨롭시키다. Die Richtung ist von oben nach unten — von Neulingen an Vorgesetzte gerichtet wirkt es unhöflich. Unter Gleichrangigen ist 같이 디벨롭해 보자 natürlich.", "en": "Used as 디벨롭하다 / 디벨롭시키다. It flows downward, so a new hire telling a manager their plan needs 디벨롭 sounds rude. Between peers, 같이 디벨롭해 보자 (let us build on it together) is natural.", "es": "Se usa como 디벨롭하다 / 디벨롭시키다. Va de arriba abajo: que un novato se lo diga al jefe suena grosero. Entre iguales, 같이 디벨롭해 보자 es natural.", "ja": "디벨롭하다・디벨롭시키다の形。上から下への指示なので、新入社員が上司の企画に対して使うと無礼に響く。同僚同士なら같이 디벨롭해 보자が自然。", "vi": "Dùng dạng 디벨롭하다 / 디벨롭시키다. Lệnh đi từ trên xuống, nên lính mới nói với sếp thì nghe hỗn. Giữa đồng nghiệp, 같이 디벨롭해 보자 lại rất tự nhiên."}'::jsonb, '{컨펌,급여체,야근각,넵병}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Flesh it out / develop it further"}, {"lang": "🇯🇵 JA", "text": "内容を詰める"}, {"lang": "🇨🇳 ZH", "text": "再深化一下"}, {"lang": "🇻🇳 VI", "text": "Triển khai sâu thêm"}, {"lang": "🇪🇸 ES", "text": "Desarrollarlo más"}, {"lang": "🇩🇪 DE", "text": "Weiter ausarbeiten"}]'::jsonb),
('491', '컨펌', 'Keon-peom', 'work', null, '윗사람의 승인·결재', '{"de": "Freigabe vom Chef", "en": "Sign-off from the boss", "es": "Visto bueno del jefe", "ja": "上司の承認", "vi": "Sự phê duyệt của sếp"}'::jsonb, '[컨펌]', '[{"type": "명사", "examples": [{"de": "Hat das die Teamleitung freigegeben? Sonst können wir es nicht rausschicken.", "es": "¿Esto ya tiene el visto bueno del jefe de equipo? Si no, no lo podemos enviar.", "ja": "これチーム長の承認下りた?まだなら送れないよ。", "vi": "Cái này sếp nhóm duyệt chưa? Chưa thì chưa gửi được.", "eng": "Did this get the team leader''s sign-off? If not, we cannot send it.", "kor": "이거 팀장님 컨펌 났어? 아직이면 못 보내."}], "definition": "영어 confirm에서 온 회사 용어. 상사나 결정권자가 문서·기획안을 보고 이대로 진행해도 좋다고 승인하는 것. 영어 confirm은 사실을 확인하다에 가깝지만, 한국 회사의 컨펌은 윗사람의 결재·허락이라는 위계 뉘앙스가 핵심이라 뜻이 겹치지 않는다.", "definition_i18n": {"de": "Büro-Konglish von englisch confirm: Vorgesetzte geben ein Dokument oder Konzept frei. Englisch confirm heißt etwas bestätigen; koreanisch 컨펌 meint Erlaubnis von oben — die Bedeutungen decken sich nicht.", "en": "Office Konglish from English confirm: a manager or decision-maker approving a document or plan to go ahead. English confirm means verifying a fact; Korean 컨펌 is about permission granted from above — the meanings do not overlap.", "es": "Konglish de oficina, del inglés confirm: que un jefe apruebe un documento o plan para seguir adelante. El confirm inglés es verificar un hecho; el 컨펌 coreano es permiso desde arriba — no coinciden.", "ja": "英語confirm由来の会社用語。上司や決裁権者が文書・企画を見てこのまま進めてよいと承認すること。英語のconfirmは事実確認に近いが、韓国の컨펌は上位者の決裁・許可という上下関係のニュアンスが核心。", "vi": "Từ công sở gốc confirm tiếng Anh: sếp hoặc người có quyền duyệt tài liệu, kế hoạch để triển khai. Confirm tiếng Anh là xác nhận sự thật, còn 컨펌 tiếng Hàn mang sắc thái cấp trên cho phép — hai nghĩa không trùng."}}]'::jsonb, '콩글리시 업무 용어로, 한국 회사에 언제 어떻게 들어왔는지는 확정되지 않았다. 광고·디자인 업계에서 먼저 자리 잡아 전 업종으로 퍼졌다는 설이 널리 이야기되지만 근거를 제시한 자료는 찾지 못했다. 2017년 직장인 대상 급여체 설문 보도에서 디벨롭과 함께 가장 많이 꼽힌 단어로 등장한다.', '{"de": "Büro-Konglish; der Weg ins koreanische Arbeitsleben ist ungeklärt. Oft heißt es, es habe sich zuerst in Werbung und Design etabliert, belegt ist das nicht. In den 2017er Presseumfragen zu 급여체 gehört es neben 디벨롭 zu den meistgenannten Wörtern.", "en": "Office Konglish whose route into Korean workplaces is unsettled. A common claim is that it took hold first in advertising and design and spread from there, but no source documents this. It appears as one of the most-cited words in 2017 press surveys on corporate-speak, alongside 디벨롭.", "es": "Konglish de oficina cuya entrada al mundo laboral coreano no está establecida. Se repite que arraigó primero en publicidad y diseño, pero ninguna fuente lo documenta. Aparece entre las palabras más citadas en las encuestas de prensa de 2017 sobre 급여체, junto a 디벨롭.", "ja": "コングリッシュの業務用語で、いつどう定着したかは未確定。広告・デザイン業界から広まったという説がよく語られるが裏付け資料は見当たらない。2017年の급여체アンケート報道で디벨롭と並び最多に挙げられた語。", "vi": "Từ Konglish công sở, chưa rõ vào tiếng Hàn khi nào và bằng con đường nào. Nhiều người nói nó bén rễ trước ở ngành quảng cáo, thiết kế nhưng không nguồn nào chứng minh. Nó nằm trong nhóm từ được nhắc nhiều nhất ở khảo sát 급여체 năm 2017, cùng 디벨롭."}'::jsonb, '컨펌받다·컨펌나다·컨펌해 주세요 꼴로 쓴다. 받는 쪽이 늘 아랫사람이라 팀장님 컨펌받았어?처럼 묻는다. 영어권 화자가 confirm의 뜻으로 알아들으면 단순한 일정 확인으로 오해하기 쉬운 대표적인 단어다.', '{"de": "Gebraucht als 컨펌받다 / 컨펌나다 / 컨펌해 주세요. Wer es einholt, ist immer die untere Ebene. Eine klassische Falle für Englischsprachige, die es als bloßes Nachfragen verstehen.", "en": "Used as 컨펌받다 / 컨펌나다 / 컨펌해 주세요. The one seeking it is always the junior, hence questions like 팀장님 컨펌받았어?. A classic trap for English speakers, who hear it as merely checking a detail.", "es": "Se usa como 컨펌받다 / 컨펌나다 / 컨펌해 주세요. Quien lo pide siempre es el subordinado. Trampa clásica para angloparlantes, que lo oyen como simple verificación.", "ja": "컨펌받다・컨펌나다・컨펌해 주세요の形で使う。求める側は常に下位者なので팀장님 컨펌받았어?のように聞く。英語話者がconfirmとして受け取ると単なる日程確認と誤解しやすい代表語。", "vi": "Dùng dạng 컨펌받다 / 컨펌나다 / 컨펌해 주세요. Người xin luôn là cấp dưới. Đây là bẫy kinh điển với người nói tiếng Anh, dễ hiểu nhầm thành xác nhận thông tin."}'::jsonb, '{디벨롭,급여체,넵병,야근각}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Sign-off / approval from above"}, {"lang": "🇯🇵 JA", "text": "上司の承認・決裁"}, {"lang": "🇨🇳 ZH", "text": "上级批准"}, {"lang": "🇻🇳 VI", "text": "Sếp duyệt"}, {"lang": "🇪🇸 ES", "text": "Visto bueno del jefe"}, {"lang": "🇩🇪 DE", "text": "Freigabe von oben"}]'::jsonb),
('492', '일잘러', 'Il-jal-leo', 'work', null, '일 잘하는 사람', '{"de": "Jemand, der seinen Job richtig gut macht", "en": "Someone who is really good at their job", "es": "Alguien que trabaja muy bien", "ja": "仕事ができる人", "vi": "Người làm việc giỏi"}'::jsonb, '[일잘러]', '[{"type": "명사", "examples": [{"de": "Herr Kim ist echt ein Arbeitsprofi — Bericht in 30 Minuten fertig.", "es": "El señor Kim es un crack del trabajo: acabó el informe en 30 minutos.", "ja": "キム代理、マジで仕事できる人。報告書30分で終わらせた。", "vi": "Anh Kim đúng là cao thủ công việc, làm xong báo cáo trong 30 phút.", "eng": "Assistant Manager Kim is such an il-jal-leo — knocked out the report in 30 minutes.", "kor": "김 대리님 진짜 일잘러다. 보고서 30분 만에 끝냈어."}], "definition": "일 + 잘 + -러(∼하는 사람). 단순히 시킨 일을 해내는 사람이 아니라, 일의 배경과 우선순위를 파악해 효율적으로 좋은 결과를 내는 사람을 가리킨다. 반대말은 일못러.", "definition_i18n": {"de": "Aus 일(Arbeit) + 잘(gut) + -러(-er). Nicht bloß jemand, der Aufgaben abarbeitet, sondern wer Kontext und Prioritäten erfasst und liefert. Gegenteil: 일못러.", "en": "From 일(work) + 잘(well) + -러(-er). Not just someone who finishes assigned tasks, but someone who grasps the context and priorities and delivers real results. The opposite is 일못러.", "es": "De 일(trabajo) + 잘(bien) + -러(-dor). No es quien solo cumple lo que le mandan, sino quien entiende el contexto y las prioridades y entrega resultados. Lo contrario es 일못러.", "ja": "일(仕事)+잘(上手に)+-러(∼する人)。ただ言われた仕事をこなす人ではなく、背景と優先順位を掴んで効率よく成果を出す人。反対語は일못러。", "vi": "Từ 일(công việc) + 잘(giỏi) + -러(người ∼). Không chỉ là người làm xong việc được giao, mà là người nắm bối cảnh, biết ưu tiên và ra kết quả. Trái nghĩa là 일못러."}}]'::jsonb, '2010년대 후반부터 직장인 커뮤니티와 채용 플랫폼 콘텐츠를 통해 퍼졌다. ∼러는 영어 -er를 한글로 옮겨 ∼하는 사람이라는 뜻으로 쓰는 접미사로, 프로불편러·자낳괴 등과 같은 시기의 조어 유행에서 나왔다. 개인의 주체적 성장을 중시하는 MZ세대 직장관을 보여 주는 말로 언론에 자주 인용된다. 최초 사용자나 정확한 등장 시점은 확인되지 않았다.', '{"de": "Verbreitete sich ab den späten 2010ern über Büro-Communities und Recruiting-Plattformen. Das Suffix -러 ist das englische -er in Hangul, aus derselben Wortschöpfungswelle wie 프로불편러. Gilt in der Presse als Beleg für das wachstumsorientierte Arbeitsethos der MZ-Generation. Erstverwendung nicht belegt.", "en": "Spread from the late 2010s through office-worker communities and job-platform content. The -러 suffix is English -er written in Korean, part of the same coinage wave as 프로불편러. Often cited in the press as evidence of an MZ-generation work ethic centred on personal growth. No first coiner or exact date is documented.", "es": "Se difundió desde finales de los 2010 en comunidades de oficinistas y portales de empleo. El sufijo -러 es el -er inglés escrito en coreano, de la misma ola que 프로불편러. La prensa lo cita como muestra de la ética laboral de la generación MZ. No hay primer uso documentado.", "ja": "2010年代後半から会社員コミュニティや求人プラットフォームのコンテンツで広まった。∼러は英語-erをハングルで写した接尾辞で、프로불편러などと同時期の造語ブームの産物。個人の成長を重視するMZ世代の仕事観を示す語として報道でよく引かれる。初出や造語者は未確認。", "vi": "Lan rộng từ cuối thập niên 2010 qua cộng đồng dân văn phòng và nội dung của các nền tảng tuyển dụng. Hậu tố -러 là -er tiếng Anh viết bằng Hangul, cùng làn sóng với 프로불편러. Báo chí hay dẫn từ này như biểu hiện quan niệm làm việc của thế hệ MZ. Chưa rõ người dùng đầu tiên."}'::jsonb, '칭찬이라 동료나 후배를 두고 3인칭으로 쓰면 자연스럽다. 상사에게 대놓고 일잘러세요라고 하면 아랫사람이 윗사람을 평가하는 말투가 되어 어색하다. 반대말 일못러는 험담이므로 본인 앞에서는 절대 쓰지 않는다.', '{"de": "Ein Lob — in der dritten Person über Kolleg*innen natürlich. Der Chefin direkt gesagt klingt es nach Bewertung von unten. Das Gegenteil 일못러 ist eine Beleidigung, nie ins Gesicht sagen.", "en": "It is praise, so using it in the third person about a colleague or junior is natural. Saying it straight to your boss sounds like you are grading them, which is awkward. The opposite, 일못러, is an insult — never say it to someone face to face.", "es": "Es un elogio: natural en tercera persona sobre un compañero. Decírselo al jefe en la cara suena a evaluarlo. Su contrario, 일못러, es un insulto — nunca en su cara.", "ja": "褒め言葉なので同僚や後輩を三人称で指すのが自然。上司に面と向かって言うと部下が評価する口調になり不自然。反対語일못러は悪口なので本人の前では使わない。", "vi": "Đây là lời khen, dùng ở ngôi thứ ba về đồng nghiệp là tự nhiên. Nói thẳng với sếp thì nghe như đang đánh giá cấp trên. Trái nghĩa 일못러 là lời chê, tuyệt đối không nói trước mặt."}'::jsonb, '{일못러,갓생,알잘딱깔센,급여체}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "A real work machine / ace"}, {"lang": "🇯🇵 JA", "text": "仕事ができる人"}, {"lang": "🇨🇳 ZH", "text": "工作能手"}, {"lang": "🇻🇳 VI", "text": "Người làm việc giỏi"}, {"lang": "🇪🇸 ES", "text": "Crack en el trabajo"}, {"lang": "🇩🇪 DE", "text": "Arbeitsprofi"}]'::jsonb),
('493', '고스팅', 'Go-seu-ting', 'work', 'love', '말없이 연락 끊고 사라지기', '{"de": "Spurlos verschwinden", "en": "Vanishing without a word", "es": "Desaparecer sin decir nada", "ja": "何も言わず音信不通になること", "vi": "Biến mất không một lời"}'::jsonb, '[고스팅]', '[{"type": "명사", "examples": [{"de": "Der Neue hat am ersten Tag geghostet — geht nicht mal ans Telefon.", "es": "El nuevo hizo ghosting el primer día. Ni contesta llamadas.", "ja": "新入社員が初日にゴースティングしたって。連絡も取れないらしい。", "vi": "Nhân viên mới ghosting ngay ngày đầu, gọi cũng không nghe.", "eng": "The new hire ghosted on day one — not even answering calls.", "kor": "신입이 출근 첫날 고스팅했대. 연락도 안 받는대."}], "definition": "영어 ghost(유령)에 -ing를 붙인 말. 아무 설명 없이 연락을 끊고 사라지는 행동. 원래는 연인이나 썸 관계에서 쓰였는데, 한국에서는 채용 맥락으로 넓어져 합격 통보를 받고 출근일에 그냥 나타나지 않거나 며칠 다니다 연락이 끊기는 신입사원의 행동까지 가리킨다.", "definition_i18n": {"de": "Englisch ghost + -ing: den Kontakt abbrechen und ohne Erklärung verschwinden. Ursprünglich aus dem Dating, in Korea aber auf Personalfragen ausgeweitet — Neueingestellte, die zusagen und nie erscheinen oder nach Tagen abtauchen.", "en": "English ghost + -ing: cutting contact and disappearing with no explanation. Originally about dating, but in Korea it widened to hiring — a new hire who accepts the offer and simply never turns up, or vanishes after a few days.", "es": "Del inglés ghost + -ing: cortar el contacto y desaparecer sin explicación. Nació en el terreno sentimental, pero en Corea se extendió a la contratación: el recién contratado que acepta y no aparece, o se esfuma a los pocos días.", "ja": "英語ghost(幽霊)+-ing。何の説明もなく連絡を絶って消える行動。元は恋愛関係の語だが、韓国では採用の文脈に広がり、内定を受けながら出勤日に現れない、数日で音信不通になる新入社員の行動まで指す。", "vi": "Từ ghost (ma) + -ing tiếng Anh: cắt liên lạc và biến mất không lời giải thích. Vốn dùng trong chuyện yêu đương, ở Hàn mở rộng sang tuyển dụng — người đã nhận việc nhưng không đến làm, hoặc đi vài hôm rồi mất hút."}}]'::jsonb, '영어권 데이팅 용어가 2010년대 후반 한국에 들어왔다. 2019년 사람인 등 채용 플랫폼이 취업시장 신조어로 소개하면서 직장 용어로 자리 잡았다. 다만 연애 맥락과 채용 맥락 중 한국에서 어느 쪽이 먼저 퍼졌는지는 자료마다 설명이 갈린다. 원래 한국어에 있던 잠수 타다와 뜻이 거의 같아 둘이 섞여 쓰인다.', '{"de": "Ein englischer Dating-Begriff, der in den späten 2010ern nach Korea kam. Jobportale wie Saramin führten ihn 2019 als Arbeitsmarkt-Slang ein und verankerten ihn im Büro. Quellen widersprechen sich, welche Bedeutung in Korea zuerst ankam. Er deckt sich fast völlig mit dem heimischen 잠수 타다.", "en": "An English dating term that reached Korea in the late 2010s. Recruiting platforms such as Saramin presented it as job-market slang in 2019, which fixed it as workplace vocabulary. Sources disagree on whether the dating or the hiring sense spread first in Korea. It overlaps almost entirely with the native 잠수 타다, and the two are used interchangeably.", "es": "Término inglés del ámbito sentimental llegado a Corea a finales de los 2010. Portales como Saramin lo presentaron en 2019 como jerga del mercado laboral, y así se fijó. Las fuentes discrepan sobre qué sentido cuajó antes. Se solapa casi del todo con el coreano 잠수 타다.", "ja": "英語圏の恋愛用語が2010年代後半に韓国へ入った。2019年にサラミンなど採用プラットフォームが就職市場の新語として紹介し職場用語として定着。ただし恋愛と採用のどちらが先に広まったかは資料で説明が分かれる。既存の韓国語잠수 타다とほぼ同義で混用される。", "vi": "Thuật ngữ hẹn hò tiếng Anh vào Hàn cuối thập niên 2010. Năm 2019 các nền tảng tuyển dụng như Saramin giới thiệu nó như tiếng lóng thị trường việc làm, từ đó thành từ công sở. Các nguồn không thống nhất nghĩa nào lan trước. Nó gần trùng hoàn toàn với 잠수 타다 sẵn có."}'::jsonb, '하는 쪽을 비판하는 말이라 고스팅 당했다처럼 피해자 입장에서 많이 쓴다. 회사 맥락과 연애 맥락 둘 다 자연스럽고, 같은 뜻으로 잠수 탔다고도 한다.', '{"de": "Der Vorwurf trifft die verschwindende Seite, daher meist 고스팅 당했다 (ich wurde geghostet). Passt im Job wie beim Dating; 잠수 탔다 meint dasselbe.", "en": "It blames the one who disappears, so it mostly appears as 고스팅 당했다 (I got ghosted). Natural in both work and dating contexts; 잠수 탔다 says the same thing.", "es": "Culpa a quien desaparece, así que suele decirse 고스팅 당했다 (me hicieron ghosting). Vale igual en lo laboral y en lo sentimental; 잠수 탔다 significa lo mismo.", "ja": "する側を批判する語なので고스팅 당했다のように被害者の立場でよく使う。会社の文脈でも恋愛の文脈でも自然で、同義で잠수 탔다とも言う。", "vi": "Từ này chê người biến mất nên thường dùng ở thế bị hại: 고스팅 당했다. Hợp cả bối cảnh công việc lẫn tình cảm; 잠수 탔다 cũng cùng nghĩa."}'::jsonb, '{잠수이별,안읽씹,이퇴백,읽씹}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Ghosting"}, {"lang": "🇯🇵 JA", "text": "ゴースティング(音信不通)"}, {"lang": "🇨🇳 ZH", "text": "人间蒸发式失联"}, {"lang": "🇻🇳 VI", "text": "Ghosting (biến mất)"}, {"lang": "🇪🇸 ES", "text": "Ghosting"}, {"lang": "🇩🇪 DE", "text": "Ghosting"}]'::jsonb),
('494', '중고신입', 'Jung-go-sin-ip', 'work', null, '경력을 접고 신입으로 다시 지원하는 사람', '{"de": "Gebrauchter Neuling — mit Erfahrung, aber Bewerbung als Berufseinsteiger", "en": "A used newbie — experienced but applying entry-level", "es": "Novato de segunda mano: con experiencia pero postula como junior", "ja": "経験ありで新卒枠に応募する中古新人", "vi": "Tân binh đã qua sử dụng — có kinh nghiệm nhưng ứng tuyển vị trí mới vào"}'::jsonb, '[중고시닙]', '[{"type": "명사", "examples": [{"de": "Ich habe zwei Jahre gearbeitet, gekündigt und mich wieder als Einsteiger beworben.", "es": "Trabajé dos años, lo dejé y volví a postular como novato de segunda mano.", "ja": "2年勤めて辞めて、中古新人としてまた応募した。", "vi": "Tớ làm hai năm rồi nghỉ, nộp lại hồ sơ diện tân binh đã qua sử dụng.", "eng": "I worked two years, quit, and reapplied as a jung-go-sin-ip.", "kor": "나 2년 다니다 관두고 중고신입으로 다시 지원했어."}], "definition": "직장 경력이 있으면서도 경력직 인정을 포기하고 신입 공채에 지원하는 사람. 연봉·직무 전환·회사 규모 때문에 경력을 버리는 선택이라, 중고차처럼 한 번 쓴 신입이라는 자조가 담겼다. 사람인이 기업 560곳에 물은 조사에서 기업이 보는 중고신입의 평균 연차는 2.3년, 나이 마지노선은 32.3세였다.", "definition_i18n": {"de": "Wer Berufserfahrung hat, auf deren Anrechnung verzichtet und sich trotzdem auf eine Einsteigerstelle bewirbt — wegen Gehalt, Branchenwechsel oder größerer Firma. Der Name scherzt über einen gebrauchten Neuling. Laut Saramin-Umfrage unter 560 Firmen: im Schnitt 2,3 Jahre Erfahrung, Altersgrenze 32,3.", "en": "Someone with work experience who gives up credit for it and applies to an entry-level opening anyway — for pay, a career switch, or a bigger company. The name jokes that they are a pre-owned new hire, like a used car. In a Saramin survey of 560 firms, companies pegged the average at 2.3 years of experience and an age ceiling of 32.3.", "es": "Quien tiene experiencia pero renuncia a que se la reconozcan y se presenta a una vacante junior — por sueldo, cambio de sector o empresa más grande. El nombre bromea con que es un novato de segunda mano. En una encuesta de Saramin a 560 empresas: media de 2,3 años y tope de 32,3 de edad.", "ja": "職歴がありながら経歴職の認定を諦め新卒公募に応募する人。年収・職種転換・会社規模のために経歴を捨てる選択で、中古車のような一度使った新人という自嘲が込もる。サラミンの企業560社調査では平均2.3年目、年齢の限界は32.3歳。", "vi": "Người đã có kinh nghiệm nhưng bỏ qua việc được công nhận thâm niên để ứng tuyển vị trí tân binh — vì lương, đổi ngành hay công ty lớn hơn. Tên gọi đùa rằng đây là tân binh đã qua sử dụng như xe cũ. Khảo sát 560 doanh nghiệp của Saramin: trung bình 2,3 năm, tuổi trần 32,3."}}]'::jsonb, '대기업 신입 공채 경쟁이 심해지며 채용 담당자들 사이에서 먼저 쓰이다 구직자들에게 퍼졌다는 설명이 일반적이지만, 정확한 등장 시점을 밝힌 자료는 찾지 못했다. 사물에 쓰던 중고를 사람에게 붙이는 발상이 문송합니다·이퇴백 같은 자조적 취업 신조어와 같은 흐름에 있다.', '{"de": "Üblicherweise heißt es, Recruiter hätten es zuerst benutzt, als der Wettbewerb um Einsteigerstellen zunahm; Bewerber*innen übernahmen es. Ein Datum nennt keine Quelle. 중고 (gebraucht) auf Menschen anzuwenden stellt es neben 문송합니다 und 이퇴백.", "en": "The usual account is that recruiters used it first as competition for entry-level openings intensified, and job-seekers picked it up — but no source pins down a date. Attaching 중고 (second-hand), normally used for objects, to a person puts it in the same self-deprecating job-market family as 문송합니다 and 이퇴백.", "es": "Se suele decir que lo usaron primero los reclutadores al endurecerse la competencia por los puestos junior, y luego los candidatos — pero ninguna fuente fija la fecha. Aplicar 중고 (de segunda mano), propio de objetos, a una persona lo sitúa junto a 문송합니다 e 이퇴백.", "ja": "大企業の新卒公募競争が激化する中で採用担当者が先に使い、求職者に広まったという説明が一般的だが、時期を特定した資料は見当たらない。物に使う중고を人に付ける発想は문송합니다・이퇴백と同じ自嘲系の流れ。", "vi": "Cách giải thích phổ biến là nhà tuyển dụng dùng trước khi cạnh tranh vào vị trí mới vào gay gắt hơn, rồi ứng viên dùng theo — nhưng không nguồn nào xác định thời điểm. Gắn 중고 (đồ cũ) cho con người đặt từ này cùng nhóm tự giễu với 문송합니다 và 이퇴백."}'::jsonb, '채용 공고·면접·취업 커뮤니티에서 일상적으로 쓰는 말이라 비하로 받아들여지지는 않는다. 면접에서 저는 중고신입인데요처럼 본인이 먼저 꺼내도 어색하지 않다.', '{"de": "In Stellenanzeigen, Interviews und Karriereforen so gebräuchlich, dass es nicht abwertend wirkt. Sich im Vorstellungsgespräch mit 저는 중고신입인데요 vorzustellen ist normal.", "en": "Common enough in job ads, interviews and career forums that it is not taken as a slur. Introducing yourself with 저는 중고신입인데요 in an interview is perfectly normal.", "es": "Se usa a diario en ofertas, entrevistas y foros, así que no se toma como insulto. Presentarte con 저는 중고신입인데요 en una entrevista es normal.", "ja": "求人・面接・就活コミュニティで日常的に使うため蔑称とは受け取られない。面接で저는 중고신입인데요と自分から言っても不自然ではない。", "vi": "Xuất hiện thường xuyên trong tin tuyển dụng, phỏng vấn và diễn đàn nên không bị coi là miệt thị. Tự giới thiệu 저는 중고신입인데요 khi phỏng vấn là bình thường."}'::jsonb, '{이퇴백,퇴준생,문송합니다}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Experienced applicant taking an entry-level slot"}, {"lang": "🇯🇵 JA", "text": "中古新人"}, {"lang": "🇨🇳 ZH", "text": "二手新人"}, {"lang": "🇻🇳 VI", "text": "Tân binh đã qua sử dụng"}, {"lang": "🇪🇸 ES", "text": "Novato de segunda mano"}, {"lang": "🇩🇪 DE", "text": "Gebrauchter Neuling"}]'::jsonb);
